code.cpp:
class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int n = nums.size();
        int m = 2 * numSlots;
        int total = 1 << m;
        vector<int> dp(total, -1);
        dp[0] = 0;
        int ans = 0;

        for (int mask = 0; mask < total; ++mask) {
            if (dp[mask] < 0) continue;
            int used = __builtin_popcount(mask);
            if (used == n) {
                if (dp[mask] > ans) ans = dp[mask];
                continue;
            }
            for (int p = 0; p < m; ++p) {
                if (mask & (1 << p)) continue;
                int slot = p / 2 + 1;
                int nm = mask | (1 << p);
                int val = dp[mask] + (nums[used] & slot);
                if (val > dp[nm]) dp[nm] = val;
            }
        }

        return ans;
    }
};
